/**
 * The developer map ("lab"), pure part: its map definition and the "lab" preset that fills a state with every
 * crop stage, placeable, machine, node and forage good the map has spots for. No Phaser (unit tested).
 *
 * The map itself is generated by scripts/generate-lab-map.mjs into ./lab/lab-map.json. It is registered at
 * runtime only (src/dev/lab.ts), so normal play never knows it exists.
 */
import { crops, fish, items, machines, mapsData, npcs, placeables, plots } from '../data';
import type { MapDef } from '../data';
import type { GameState, PlacedObject } from '../state/GameState';
import { preserveOf } from '../systems/preserves';
import { treeDef } from '../systems/trees';
import lab from './lab/lab-map.json';

export const LAB_MAP = 'lab';
export const LAB_SCENE = 'Lab';

export interface LabLayout {
  cropRows: { crop: string; tx: number; ty: number; stages: number }[];
  soil: {
    kind: 'tilled' | 'watered' | 'fertilized' | 'weeds' | 'dirt';
    tiles: [number, number][];
  }[];
  placed: { type: string; tx: number; ty: number }[];
  nodes: { node: string; tx: number; ty: number }[];
  forage: { item: string; tx: number; ty: number }[];
  villagers: { npc: string; tx: number; ty: number }[];
}

export interface LabMapFile {
  w: number;
  h: number;
  start: { tx: number; ty: number; facing: 'up' | 'down' | 'left' | 'right' };
  ground: number[];
  collision: number[];
  objects: {
    id: number;
    name: string;
    type: string;
    x: number;
    y: number;
    width: number;
    height: number;
    properties?: { name: string; type: string; value: unknown }[];
  }[];
  art: { names: string[]; layers: Record<string, number[]> };
  lights: { type: string; tx: number; ty: number }[];
  blooms: { x: number; y: number; n: number }[];
  layout: LabLayout;
}

export const labMap = lab as unknown as LabMapFile;

/** The lab's entry in mapsData (outdoor farmland, so soil, tilling and the day tint work as on the farm). */
export const LAB_DEF: MapDef = {
  scene: LAB_SCENE,
  file: '',
  tillable: [1, 2],
  outdoor: true,
  farmland: true,
};

let registered = false;

/**
 * Make the lab a known map: saves and scenarios on it validate, fish bite in its water (the farm pond's fish).
 * Call only after the Preload scene ran (it loads every map in mapsData by file; the lab is added to the
 * tilemap cache directly). Idempotent.
 */
export function registerLabMapDef(): void {
  if (registered) return;
  registered = true;
  mapsData.maps[LAB_MAP] = LAB_DEF;
  for (const f of fish) if (f.maps.includes('farm')) f.maps.push(LAB_MAP);
}

export const labRegistered = (): boolean => registered;

/** A machine's ready output, worked out from its own recipes (so the preset never names a stale item). */
function readyOutput(type: string): { item: string; of?: string; q?: number } | null {
  if (!machines[type]) return null;
  for (const id of Object.keys(items)) {
    const out = preserveOf({ item: id }, type);
    if (out) return out;
  }
  return null;
}

/**
 * A placeable's data "in use and ready": animals at home with a product waiting, a machine finished (its output
 * worked out from its recipes), a fruit tree grown and bearing, a silo with hay. Empty for the rest.
 */
export function readyPlacedData(type: string): Record<string, unknown> {
  const def = placeables[type];
  const data: Record<string, unknown> = {};
  if (!def) return data;
  if (def.behavior === 'animalHouse')
    data['house'] = { n: 2, fed: false, ready: 1, petted: false, joy: 3 };
  else if (def.behavior === 'jar') {
    const out = readyOutput(type);
    if (out) data['jar'] = { out, days: 0 };
  } else if (def.behavior === 'fruitTree') {
    const t = treeDef({ id: 0, type, tx: 0, ty: 0, data: {} });
    if (t) data['tree'] = { age: t.growDays, timer: 0, fruit: Math.min(2, t.cap) };
  } else if (def.behavior === 'silo') data['stock'] = { hay: 40 };
  return data;
}

/**
 * Fill the state with the lab's showcase: every crop at every stage, the soil states, every placeable (animals in
 * their houses, machines ready, fruit trees grown and bearing), the ore nodes and some forage goods. Owns every
 * plot so the beds (which sit at farm plot coordinates) can be tilled.
 */
export function applyLabPreset(s: GameState): void {
  const L = labMap.layout;
  s.plots = Object.keys(plots);
  for (const r of L.cropRows) {
    if (!crops[r.crop]) continue; // a crop removed since the lab was generated: skip its row
    const stages = crops[r.crop]!.stageDays.length;
    for (let st = 0; st <= stages; st++)
      s.farm.tiles[`${r.tx + st},${r.ty}`] = {
        watered: false,
        crop: { cropId: r.crop, stage: st, daysInStage: 0, regrow: false },
      };
  }
  const fert = Object.keys(items).find((id) => items[id]?.type === 'fertilizer');
  for (const group of L.soil)
    for (const [tx, ty] of group.tiles) {
      const key = `${tx},${ty}`;
      if (group.kind === 'tilled') s.farm.tiles[key] = { watered: false, crop: null };
      else if (group.kind === 'watered') s.farm.tiles[key] = { watered: true, crop: null };
      else if (group.kind === 'fertilized')
        s.farm.tiles[key] = { watered: false, crop: null, ...(fert ? { fert } : {}) };
      else if (group.kind === 'weeds') s.farm.weeds[key] = true;
    }
  const list: PlacedObject[] = (s.placed[LAB_MAP] ??= []);
  for (const p of L.placed)
    if (placeables[p.type])
      list.push({
        id: s.nextPlacedId++,
        type: p.type,
        tx: p.tx,
        ty: p.ty,
        data: readyPlacedData(p.type),
      });
  const nodes = (s.nodes[LAB_MAP] ??= {});
  for (const n of L.nodes) nodes[`${n.tx},${n.ty}`] = n.node;
  const forage = (s.forage[LAB_MAP] ??= {});
  for (const f of L.forage)
    if (items[f.item]?.type === 'forage') forage[`${f.tx},${f.ty}`] = f.item;
}

/** Villagers who have a spot on the lab map (the dev tools stand them there in lab scenarios). */
export const labVillagers = (): LabLayout['villagers'] =>
  labMap.layout.villagers.filter((v) => npcs[v.npc]);
